import type { Metadata } from "next";
import { Poppins } from "next/font/google";

import "./globals.css";

const poppins = Poppins({
  subsets: ["latin"],
  weight: ["400", "500", "600", "700"],
  variable: "--font-poppins",
  display: "swap",
});

export const metadata: Metadata = {
  title: {
    default: "CuroAid | Home Healthcare Services",
    template: "%s | CuroAid",
  },
  description:
    "CuroAid provides professional home healthcare services including Doctor at Home, home nursing, physiotherapy, elder care, wound care and more.",
  metadataBase: new URL("https://curoaid.com"),
  alternates: {
    canonical: "/",
  },
  openGraph: {
    title: "CuroAid | Home Healthcare Services",
    description:
      "Professional, personalized and compassionate healthcare services delivered to your doorstep.",
    url: "https://curoaid.com",
    siteName: "CuroAid",
    type: "website",
  },
  robots: {
    index: true,
    follow: true,
  },
};

export default function RootLayout({
  children,
}: Readonly<{
  children: React.ReactNode;
}>) {
  return (
    <html lang="en">
      <body className={`${poppins.variable} font-sans`}>
        {children}
      </body>
    </html>
  );
}